{
  "summary": "构建中文双水箱供水系统，采用内置封闭输水模拟，包含总览与趋势画面。",
  "operations": [
    {
      "op": "project.create",
      "project": {
        "schemaVersion": 1,
        "id": "flex_hmi_water_system",
        "name": "双水箱供水系统",
        "system": {
          "mode": "visualization"
        },
        "devices": [],
        "pages": [
          {
            "id": "overview",
            "name": "工艺总览",
            "width": 1280,
            "height": 720,
            "background": "#ffffff",
            "components": []
          },
          {
            "id": "trend",
            "name": "高位水箱趋势",
            "width": 1280,
            "height": 720,
            "background": "#ffffff",
            "components": []
          }
        ],
        "customSymbols": []
      }
    },
    {
      "op": "device.upsert",
      "device": {
        "id": "pump_01",
        "name": "供水泵",
        "protocol": "sim",
        "host": "127.0.0.1",
        "port": 502,
        "unitId": 1,
        "polling": 1000,
        "timeout": 1000,
        "tags": [
          {
            "id": "pump_running",
            "name": "泵运行状态",
            "address": 1,
            "type": "Bool",
            "memory": 0,
            "divisor": 1,
            "initial": 0,
            "unit": "",
            "sim": "manual",
            "writable": true
          },
          {
            "id": "pump_command",
            "name": "泵控制命令",
            "address": 2,
            "type": "Bool",
            "memory": 0,
            "divisor": 1,
            "initial": 0,
            "unit": "",
            "sim": "manual",
            "writable": true
          }
        ]
      }
    },
    {
      "op": "device.upsert",
      "device": {
        "id": "tank_source",
        "name": "原水箱",
        "protocol": "sim",
        "host": "127.0.0.1",
        "port": 502,
        "unitId": 1,
        "polling": 1000,
        "timeout": 1000,
        "tags": [
          {
            "id": "source_level",
            "name": "原水箱液位",
            "address": 1,
            "type": "Float32",
            "memory": 0,
            "divisor": 1,
            "initial": 65,
            "unit": "m³",
            "sim": "wave",
            "writable": false
          },
          {
            "id": "source_low",
            "name": "原水箱低液位报警",
            "address": 2,
            "type": "Bool",
            "memory": 0,
            "divisor": 1,
            "initial": 0,
            "unit": "",
            "sim": "wave",
            "writable": false
          }
        ]
      }
    },
    {
      "op": "device.upsert",
      "device": {
        "id": "tank_destination",
        "name": "高位水箱",
        "protocol": "sim",
        "host": "127.0.0.1",
        "port": 502,
        "unitId": 1,
        "polling": 1000,
        "timeout": 1000,
        "tags": [
          {
            "id": "destination_level",
            "name": "高位水箱液位",
            "address": 1,
            "type": "Float32",
            "memory": 0,
            "divisor": 1,
            "initial": 30,
            "unit": "m³",
            "sim": "wave",
            "writable": false
          },
          {
            "id": "destination_high",
            "name": "高位水箱高液位报警",
            "address": 2,
            "type": "Bool",
            "memory": 0,
            "divisor": 1,
            "initial": 0,
            "unit": "",
            "sim": "wave",
            "writable": false
          }
        ]
      }
    },
    {
      "op": "page.upsert",
      "page": {
        "id": "overview",
        "name": "工艺总览",
        "width": 1280,
        "height": 720,
        "background": "#ffffff",
        "components": [
          {
            "id": "tank_source",
            "kind": "tank",
            "label": "原水箱",
            "x": 100,
            "y": 100,
            "w": 300,
            "h": 200,
            "tagId": "tank_source",
            "valueTag": "source_level",
            "color": "#343c43",
            "fontSize": 16,
            "locked": false,
            "ports": {
              "left": {
                "x": 0.5,
                "y": 0.5
              },
              "right": {
                "x": 0.5,
                "y": 0.5
              }
            }
          },
          {
            "id": "pump",
            "kind": "pump",
            "label": "供水泵",
            "x": 500,
            "y": 100,
            "w": 200,
            "h": 150,
            "tagId": "pump_01",
            "valueTag": "pump_running",
            "color": "#343c43",
            "fontSize": 16,
            "locked": false,
            "ports": {
              "left": {
                "x": 0.5,
                "y": 0.5
              },
              "right": {
                "x": 0.5,
                "y": 0.5
              }
            }
          },
          {
            "id": "tank_destination",
            "kind": "tank",
            "label": "高位水箱",
            "x": 800,
            "y": 100,
            "w": 300,
            "h": 200,
            "tagId": "tank_destination",
            "valueTag": "destination_level",
