                "y": 0.5
              },
              "right": {
                "x": 0.5,
                "y": 0.5
              }
            }
          },
          {
            "id": "pump_command",
            "kind": "switch",
            "label": "泵启停开关",
            "x": 100,
            "y": 350,
            "w": 200,
            "h": 60,
            "tagId": "pump_command",
            "valueTag": "pump_running",
            "color": "#343c43",
            "fontSize": 16,
            "locked": false,
            "ports": {
              "left": {
                "x": 0.5,
                "y": 0.5
              },
              "right": {
                "x": 0.5,
                "y": 0.5
              }
            }
          },
          {
            "id": "flow_display",
            "kind": "chart",
            "label": "当前流量",
            "x": 500,
            "y": 350,
            "w": 300,
            "h": 100,
            "tagId": "pump_command",
            "valueTag": "pump_running",
            "color": "#343c43",
            "fontSize": 16,
            "locked": false,
            "ports": {
              "left": {
                "x": 0.5,
                "y": 0.5
              },
              "right": {
                "x": 0.5,
                "y": 0.5
              }
            }
          },
          {
            "id": "volume_display",
            "kind": "chart",
            "label": "总水量",
            "x": 500,
            "y": 500,
            "w": 300,
            "h": 100,
            "tagId": "pump_command",
            "valueTag": "pump_running",
            "color": "#343c43",
            "fontSize": 16,
            "locked": false,
            "ports": {
              "left": {
                "x": 0.5,
                "y": 0.5
              },
              "right": {
                "x": 0.5,
                "y": 0.5
              }
            }
          },
          {
            "id": "low_alarm",
            "kind": "alarm",
            "label": "低液位报警",
            "x": 100,
            "y": 550,
            "w": 200,
            "h": 60,
            "tagId": "tank_source",
            "valueTag": "source_low",
            "color": "#343c43",
            "fontSize": 16,
            "locked": false,
            "ports": {
              "left": {
                "x": 0.5,
                "y": 0.5
              },
              "right": {
                "x": 0.5,
                "y": 0.5
              }
            }
          },
          {
            "id": "high_alarm",
            "kind": "alarm",
            "label": "高液位报警",
            "x": 800,
            "y": 550,
            "w": 200,
            "h": 60,
            "tagId": "tank_destination",
            "valueTag": "destination_high",
            "color": "#343c43",
            "fontSize": 16,
            "locked": false,
            "ports": {
              "left": {
                "x": 0.5,
                "y": 0.5
              },
              "right": {
                "x": 0.5,
                "y": 0.5
              }
            }
          }
        ],
        "connections": [
          {
            "id": "tank_source_to_pump",
            "from": "tank_source",
            "to": "pump",
            "label": "液位控制",
            "routeMode": "auto",
            "fromPort": "left",
            "toPort": "right"
          },
          {
            "id": "pump_to_tank_destination",
            "from": "pump",
            "to": "tank_destination",
            "label": "输送",
            "routeMode": "auto",
            "fromPort": "left",
            "toPort": "right"
          }
        ]
      }
    },
    {
      "op": "page.upsert",
      "page": {
        "id": "trend",
        "name": "高位水箱趋势",
        "width": 1280,
        "height": 720,
        "background": "#ffffff",
        "components": [
          {
            "id": "tank_destination",
            "kind": "tank",
            "label": "高位水箱",
            "x": 100,
            "y": 100,
            "w": 300,
            "h": 200,
            "tagId": "tank_destination",
            "valueTag": "destination_level",
            "color": "#343c43",
            "fontSize": 16,
            "locked": false,
            "ports": {
              "left": {
                "x": 0.5,
